:root {
  color-scheme: dark;
  --paper: #0d1117;
  --surface: #151b23;
  --surface-2: #1b232d;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --faint: #6b7686;
  --line: #263040;
  --green: #5eead4;          /* main accent (mint) */
  --accent-warm: #fb923c;    /* secondary accent (orange) */
  --accent-soft: rgba(94, 234, 212, .12);
  --warm-soft: rgba(251, 146, 60, .14);
  --radius: 14px;
  --radius-sm: 9px;
  --mono: ui-monospace, SFMono-Regular, "JetBrains Mono", Consolas, monospace;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --display: var(--sans);
}

/* ---------- base ---------- */
body {
  background:
    radial-gradient(900px 420px at 85% -80px, rgba(94, 234, 212, .10), transparent 70%),
    radial-gradient(700px 380px at -10% 10%, rgba(251, 146, 60, .07), transparent 70%),
    var(--paper);
  background-attachment: fixed;
  color: var(--ink);
}

::selection { background: rgba(94, 234, 212, .3); color: #fff; }

a:focus-visible,
.code-disclosure summary:focus-visible,
.filter-button:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 3px;
}

.skip-link { background: var(--green); color: #04201b; border-radius: 6px; }

/* ---------- header / nav ---------- */
.page-shell { width: min(1120px, calc(100% - 72px)); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 4;
  min-height: 70px;
  background: rgba(13, 17, 23, .78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}

.wordmark { color: var(--ink); }
.wordmark span { color: var(--green); }

.site-nav { color: var(--muted); }
.site-nav a:hover,
.header-link:hover { color: var(--green); }

.header-link {
  padding: 7px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--ink);
  transition: border-color 160ms ease, color 160ms ease, background 160ms ease;
}
.header-link:hover { border-color: var(--green); background: var(--accent-soft); }
.header-link span { color: var(--green); }

/* ---------- section heading ---------- */
.eyebrow {
  color: var(--faint);
  font-family: var(--mono);
  font-size: .64rem;
  letter-spacing: .14em;
}
.eyebrow-divider { color: var(--green); }

h2 {
  background: linear-gradient(120deg, #fff 30%, var(--green) 120%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.section { padding-top: 64px; }
.section-note { color: var(--muted); }

/* ---------- exercise cards ---------- */
.exercise-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.exercise-card {
  min-width: 0;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(180deg, var(--surface), rgba(21, 27, 35, .55));
  scroll-margin-top: 90px;
  transition: border-color 200ms ease, transform 200ms ease, box-shadow 200ms ease;
}
.exercise-card:hover {
  border-color: rgba(94, 234, 212, .45);
  transform: translateY(-3px);
  box-shadow: 0 14px 34px -18px rgba(94, 234, 212, .35);
}

.exercise-heading { align-items: center; gap: 14px; }

.exercise-number {
  width: 46px;
  height: 46px;
  border: 1px solid rgba(251, 146, 60, .35);
  border-radius: 12px;
  background: var(--warm-soft);
  color: var(--accent-warm);
  font-family: var(--mono);
  font-size: .85rem;
  font-weight: 700;
}

.exercise-origin,
.card-kicker {
  color: var(--faint);
  font-family: var(--mono);
  font-size: .58rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.card-kicker { margin: 0 0 8px; }

.exercise-heading h3 { color: var(--ink); font-size: 1.08rem; }
.exercise-description { color: var(--muted); font-size: .76rem; }

.exercise-demo {
  min-height: 140px;
  padding: 16px;
  border: 1px dashed #2f3b4d;
  border-radius: var(--radius-sm);
  background: rgba(8, 11, 16, .55);
}

/* ---------- demo pieces ---------- */
.greeting {
  display: inline-block;
  padding: 4px 11px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--green);
  font-size: .8rem;
  font-weight: 600;
}
.greeting-stack { gap: 8px; justify-items: start; }

.mini-card {
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
.mini-card h3 { color: var(--ink); font-size: .95rem; }
.mini-card p { color: var(--muted); font-size: .7rem; }
.mini-card a { color: var(--green); }
.mini-card a:hover { text-decoration: underline; text-underline-offset: 3px; }

.demo-card-grid { gap: 12px; }

.profile-avatar {
  border: 2px solid var(--green);
  box-shadow: 0 0 0 4px var(--accent-soft);
}

/* notifications */
.notification-list { gap: 10px; }
.notification {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  color: var(--ink);
  font-size: .74rem;
}
.notification-icon {
  width: 24px;
  height: 24px;
  border: 0;
  background: var(--accent-soft);
  color: var(--green);
}
.notification-success .notification-icon { background: rgba(94, 234, 212, .14); color: var(--green); }
.notification-warning .notification-icon { background: rgba(251, 191, 36, .16); color: #fbbf24; }
.notification-info .notification-icon    { background: rgba(125, 170, 255, .16); color: #8fb4ff; }

.content-card .card-content { color: var(--muted); }

/* product cards */
.product-card.is-sold-out { background: #12171e; opacity: .7; }
.product-card .product-price { color: var(--ink); font-size: .9rem; }
.product-rating span:first-child { color: #fbbf24; }
.product-card .stock-status {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--green);
  font-size: .62rem;
  letter-spacing: .02em;
}
.product-card.is-sold-out .stock-status {
  background: rgba(248, 113, 113, .14);
  color: #f87171;
}

/* student list */
.grade-list li {
  border-bottom: 1px solid var(--line);
  color: var(--ink);
}
.grade-list strong {
  min-width: 34px;
  padding: 1px 9px;
  border-radius: 999px;
  background: var(--warm-soft);
  color: var(--accent-warm);
  font-size: .68rem;
  text-align: center;
}

/* conditional demo */
.demo-alert {
  border-left: 3px solid #f87171;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: rgba(248, 113, 113, .1);
  color: #fca5a5;
}
.alert-success {
  border-color: var(--green);
  background: var(--accent-soft);
  color: #99f6e4;
}
.welcome-panel p { color: var(--ink); }

/* button (was unstyled before) */
.filter-button {
  padding: 8px 16px;
  border: 1px solid var(--green);
  border-radius: 999px;
  background: transparent;
  color: var(--green);
  font: 700 .7rem/1 var(--sans);
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease, transform 160ms ease;
}
.filter-button:hover { background: var(--green); color: #04201b; transform: translateY(-1px); }

/* code blocks */
.code-disclosure summary { color: var(--green); }
.code-disclosure summary::marker { color: var(--accent-warm); }
.code-disclosure pre {
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: #090c11;
  color: #c9d4e2;
  font-family: var(--mono);
}

/* ---------- footer ---------- */
.site-footer {
  margin-top: 64px;
  border-top: 1px solid var(--line);
  color: var(--faint);
}
.footer-home { color: var(--ink); }
.site-footer a:hover { color: var(--green); }
.site-footer > span { font-family: var(--mono); }

/* ---------- responsive ---------- */
@media (max-width: 850px) {
  .page-shell { width: min(100% - 48px, 700px); }
}

@media (max-width: 760px) {
  .exercise-grid { grid-template-columns: 1fr; }
}

@media (max-width: 620px) {
  .page-shell { width: min(100% - 34px, 500px); }
  .exercise-card { padding: 18px; }
  .exercise-description { min-height: 0; }
  .demo-card-grid,
  .product-grid { grid-template-columns: 1fr; }
  .welcome-panel { flex-direction: column; align-items: flex-start; }
  .section-heading h2 { font-size: 2.1rem; }
}

@media (prefers-reduced-motion: reduce) {
  .exercise-card,
  .filter-button,
  .header-link { transition: none; }
  .exercise-card:hover,
  .filter-button:hover { transform: none; }
}

const defaultAvatar =
  'data:image/svg+xml,' +
  encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80"><rect width="80" height="80" fill="#1b232d"/><circle cx="40" cy="30" r="14" fill="#5eead4"/><path d="M12 80c2-18 14-28 28-28s26 10 28 28" fill="#5eead4"/></svg>',
  );

function ProfileCard({ name, role, email, avatarUrl = defaultAvatar }) {
  return (
    <article className="mini-card profile-demo-card">
      <img className="profile-avatar" src={avatarUrl} alt="" width="64" height="64" />
      <div>
        <p className="card-kicker">PROFILE</p>
        <h3>{name}</h3>
        <p>{role}</p>
        <a href={`mailto:${email}`}>{email}</a>
      </div>
    </article>
  );
}

export default ProfileCard;
